-- Supreme-only operational notification inbox.
-- Notifications are generated by trusted database events, not customer-facing APIs.
begin;

create table if not exists public.supreme_notifications (
  id uuid primary key default gen_random_uuid(),
  category text not null check (category in ('orders','payments','delivery','inventory')),
  severity text not null default 'info' check (severity in ('info','warning','critical')),
  event_key text not null unique,
  title text not null check (char_length(title) between 1 and 120),
  body text not null check (char_length(body) between 1 and 500),
  href text not null default '/supreme',
  entity_type text,
  entity_id text,
  created_at timestamptz not null default now(),
  read_at timestamptz,
  read_by uuid references auth.users(id) on delete set null
);

create index if not exists supreme_notifications_created_idx
  on public.supreme_notifications(created_at desc, id desc);
create index if not exists supreme_notifications_unread_idx
  on public.supreme_notifications(created_at desc)
  where read_at is null;

alter table public.supreme_notifications enable row level security;
revoke all on public.supreme_notifications from public, anon, authenticated;
grant select, insert, update on public.supreme_notifications to service_role;

create or replace function private.create_supreme_order_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if tg_op = 'INSERT' then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'orders', 'info', 'order.created:' || new.id::text,
      'নতুন অর্ডার এসেছে',
      'নতুন অর্ডার গ্রহণ করা হয়েছে: ' || new.order_number || '।'
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;

    if new.payment_status::text = 'verification_pending' then
      insert into public.supreme_notifications(
        category, severity, event_key, title, body, href, entity_type, entity_id
      ) values (
        'payments', 'warning', 'payment.review:' || new.id::text,
        'পেমেন্ট যাচাই প্রয়োজন',
        'অর্ডার ' || new.order_number || ' এর পেমেন্ট যাচাই অপেক্ষমাণ।',
        '/admin/orders', 'order', new.id::text
      )
      on conflict (event_key) do nothing;
    end if;

    return new;
  end if;

  if new.payment_status::text is distinct from old.payment_status::text
     and new.payment_status::text in ('failed', 'refunded') then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'payments',
      case when new.payment_status::text = 'failed' then 'critical' else 'warning' end,
      'payment.' || new.payment_status::text || ':' || new.id::text,
      case when new.payment_status::text = 'failed' then 'পেমেন্ট ব্যর্থ হয়েছে' else 'পেমেন্ট রিফান্ড হয়েছে' end,
      'অর্ডার ' || new.order_number || ' · ' || new.payment_status::text,
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  if new.delivery_status::text is distinct from old.delivery_status::text
     and new.delivery_status::text in ('failed', 'returned') then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'delivery', 'critical',
      'delivery.' || new.delivery_status::text || ':' || new.id::text,
      case when new.delivery_status::text = 'failed' then 'ডেলিভারিতে সমস্যা হয়েছে' else 'পার্সেল ফেরত এসেছে' end,
      'অর্ডার ' || new.order_number || ' · ' || new.delivery_status::text,
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  if new.status::text is distinct from old.status::text
     and new.status::text = 'cancelled' then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'orders', 'warning', 'order.cancelled:' || new.id::text,
      'অর্ডার বাতিল হয়েছে',
      'অর্ডার ' || new.order_number || ' বাতিল করা হয়েছে।',
      '/admin/orders', 'order', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  return new;
end;
$function$;

revoke all on function private.create_supreme_order_notifications() from public, anon, authenticated;

drop trigger if exists orders_create_supreme_notifications on public.orders;
create trigger orders_create_supreme_notifications
after insert or update of status, payment_status, delivery_status on public.orders
for each row execute function private.create_supreme_order_notifications();

create or replace function private.create_supreme_low_stock_notification()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_low_stock boolean := false;
begin
  if tg_op = 'INSERT' then
    v_low_stock := new.stock <= new.low_stock_threshold;
  else
    v_low_stock := new.stock < old.stock and new.stock <= old.low_stock_threshold;
  end if;

  if v_low_stock then
    insert into public.supreme_notifications(
      category, severity, event_key, title, body, href, entity_type, entity_id
    ) values (
      'inventory',
      case when new.stock = 0 then 'critical' else 'warning' end,
      'inventory.low_stock:' || new.id::text || ':' || new.stock::text,
      case when new.stock = 0 then 'পণ্যের স্টক শেষ' else 'পণ্যের স্টক কমে গেছে' end,
      new.name || ' · অবশিষ্ট ' || new.stock::text || 'টি',
      '/admin/inventory', 'product', new.id::text
    )
    on conflict (event_key) do nothing;
  end if;

  return new;
end;
$function$;

revoke all on function private.create_supreme_low_stock_notification() from public, anon, authenticated;

drop trigger if exists products_create_supreme_low_stock_notification on public.products;
create trigger products_create_supreme_low_stock_notification
after insert or update of stock on public.products
for each row execute function private.create_supreme_low_stock_notification();


-- Preserve inclusive Dhaka-local custom date ranges for the expense ledger while
-- the order query continues to use an exclusive timestamp upper bound.
create or replace function public.supreme_dashboard_summary(
  p_start_at timestamptz default null,
  p_end_at timestamptz default null
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $function$
  with filtered_orders as (
    select o.id, o.order_number, o.created_at, o.status::text as status,
      o.total, o.payment_status, o.shipping_district, o.shipping_upazila
    from public.orders o
    where (p_start_at is null or o.created_at >= p_start_at)
      and (p_end_at is null or o.created_at < p_end_at)
  ),
  filtered_expenses as (
    select e.amount
    from public.operating_expenses e
    where (p_start_at is null or e.expense_date >= (p_start_at at time zone 'Asia/Dhaka')::date)
      and (
        p_end_at is null
        or e.expense_date <= case
          when (p_end_at at time zone 'Asia/Dhaka')::time = time '00:00:00'
            then ((p_end_at at time zone 'Asia/Dhaka')::date - 1)
          else (p_end_at at time zone 'Asia/Dhaka')::date
        end
      )
  ),
  district_totals as (
    select coalesce(nullif(pg_catalog.btrim(shipping_district), ''), 'ঠিকানা অনুপস্থিত') as district,
      pg_catalog.sum(total)::bigint as order_value,
      pg_catalog.count(*)::bigint as order_count
    from filtered_orders
    group by 1
    order by pg_catalog.sum(total) desc, district asc
    limit 10
  ),
  recent_orders as (
    select id, order_number, created_at, status, total, payment_status,
      shipping_district, shipping_upazila
    from filtered_orders
    order by created_at desc, id desc
    limit 8
  )
  select pg_catalog.jsonb_build_object(
    'order_count', (select pg_catalog.count(*) from filtered_orders),
    'order_value', coalesce((select pg_catalog.sum(total) from filtered_orders), 0),
    'paid_amount', coalesce((select pg_catalog.sum(total) from filtered_orders where payment_status = 'paid'), 0),
    'pending_payment_count', (select pg_catalog.count(*) from filtered_orders
      where payment_status is distinct from 'paid' and payment_status not in ('failed', 'cancelled')),
    'pending_order_count', (select pg_catalog.count(*) from filtered_orders
      where status not in ('delivered', 'cancelled', 'returned')),
    'operating_expense_total', coalesce((select pg_catalog.sum(amount) from filtered_expenses), 0),
    'operating_expense_count', (select pg_catalog.count(*) from filtered_expenses),
    'district_totals', coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('district', district, 'order_value', order_value, 'order_count', order_count)
      order by order_value desc, district asc) from district_totals), '[]'::jsonb),
    'recent_orders', coalesce((select pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object('id', id, 'order_number', order_number, 'created_at', created_at,
        'status', status, 'total', total, 'payment_status', payment_status,
        'shipping_district', shipping_district, 'shipping_upazila', shipping_upazila)
      order by created_at desc, id desc) from recent_orders), '[]'::jsonb)
  );
$function$;

revoke all on function public.supreme_dashboard_summary(timestamptz, timestamptz)
  from public, anon, authenticated;
grant execute on function public.supreme_dashboard_summary(timestamptz, timestamptz)
  to service_role;

commit;
